use syn::{Arm, Expr, Pat, Stmt};

use crate::{
    CollectionResult, NodeTypeSet,
    utils::{astkind_variant_from_path, executable_stmts, is_node_kind_call},
};

/// Detects various kinds of diverging statements that narrow by more than one AST node type.
pub struct EarlyDivergeDetector {
    node_types: NodeTypeSet,
}

impl EarlyDivergeDetector {
    pub fn from_run_func(run_func: &syn::ImplItemFn) -> Option<NodeTypeSet> {
        // Only look at cases where the body has more than one top-level statement.
        let stmts = executable_stmts(&run_func.block);
        if stmts.len() <= 1 {
            return None;
        }

        // Look at the first statement in the function body.
        let stmt = *stmts.first()?;

        // Check if it's `let something = match node.kind() { ... }` that diverges
        if let Stmt::Local(local) = stmt
            && let Some(init) = &local.init
            && let Expr::Match(match_expr) = &*init.expr
            && is_node_kind_call(&match_expr.expr)
        {
            let mut detector = Self { node_types: NodeTypeSet::new() };
            let result = detector.extract_variants_from_diverging_match_expr(match_expr);
            if result == CollectionResult::Incomplete || detector.node_types.is_empty() {
                return None;
            }
            return Some(detector.node_types);
        }
        // Stand-alone `match node.kind() { ... }` that diverges
        else if let Stmt::Expr(Expr::Match(match_expr), _) = stmt
            && is_node_kind_call(&match_expr.expr)
        {
            let mut detector = Self { node_types: NodeTypeSet::new() };
            let result = detector.extract_variants_from_diverging_match_expr(match_expr);
            if result == CollectionResult::Incomplete || detector.node_types.is_empty() {
                return None;
            }
            return Some(detector.node_types);
        }

        None
    }

    fn extract_variants_from_diverging_match_expr(
        &mut self,
        match_expr: &syn::ExprMatch,
    ) -> CollectionResult {
        let mut overall_result = CollectionResult::Complete;
        for arm in &match_expr.arms {
            let result = self.extract_variants_from_diverging_match_arm(arm);
            if result == CollectionResult::Incomplete {
                overall_result = CollectionResult::Incomplete;
            }
        }
        overall_result
    }

    fn extract_variants_from_diverging_match_arm(&mut self, arm: &Arm) -> CollectionResult {
        let pat = match &arm.pat {
            Pat::Guard(guard) => guard.pat.as_ref(),
            pat => pat,
        };
        match pat {
            Pat::TupleStruct(ts) => {
                if let Some(variant) = astkind_variant_from_path(&ts.path) {
                    // NOTE: If there is a guard, we assume that it may or may not be taken and collect all AST kinds
                    // regardless of the guard condition.
                    self.node_types.insert(variant);
                    CollectionResult::Complete
                } else {
                    CollectionResult::Incomplete
                }
            }
            Pat::Wild(_) => {
                // Body must be diverging (i.e., returning from function)
                if let Expr::Return(_) = *arm.body {
                    return CollectionResult::Complete;
                }
                CollectionResult::Incomplete
            }
            Pat::Or(or) => {
                let mut overall_result = CollectionResult::Complete;
                for case in &or.cases {
                    let result = match case {
                        Pat::TupleStruct(ts) => {
                            if let Some(variant) = astkind_variant_from_path(&ts.path) {
                                self.node_types.insert(variant);
                                CollectionResult::Complete
                            } else {
                                CollectionResult::Incomplete
                            }
                        }
                        _ => CollectionResult::Incomplete,
                    };
                    if result == CollectionResult::Incomplete {
                        overall_result = CollectionResult::Incomplete;
                    }
                }
                overall_result
            }
            _ => CollectionResult::Incomplete,
        }
    }
}

use syn::{Expr, ExprIf, Pat, Stmt};

use crate::{
    CollectionResult, NodeTypeSet,
    utils::{astkind_variant_from_path, executable_stmts, is_node_kind_call},
};

/// Detects top-level `if let AstKind::... = node.kind()` patterns in the `run` method.
pub struct IfElseKindDetector {
    node_types: NodeTypeSet,
}

impl IfElseKindDetector {
    pub fn from_run_func(run_func: &syn::ImplItemFn) -> Option<NodeTypeSet> {
        // Only consider when the body has exactly one top-level statement and it's an `if`.
        let stmts = executable_stmts(&run_func.block);
        if stmts.len() != 1 {
            return None;
        }
        let stmt = stmts[0];
        let Stmt::Expr(Expr::If(ifexpr), _) = stmt else { return None };
        let mut detector = Self { node_types: NodeTypeSet::new() };
        let result = detector.collect_if_chain_variants(ifexpr);
        if result == CollectionResult::Incomplete || detector.node_types.is_empty() {
            return None;
        }
        Some(detector.node_types)
    }

    /// Collects AstKind variants from an if-else chain of `if let AstKind::Xxx(..) = node.kind()`.
    /// Returns `true` if all syntax was recognized as supported, otherwise `false`, indicating that
    /// the variants collected may be incomplete and should not be treated as valid.
    fn collect_if_chain_variants(&mut self, ifexpr: &ExprIf) -> CollectionResult {
        // Extract variants from condition like `if let AstKind::Xxx(..) = node.kind()`.
        if self.extract_variants_from_if_let_condition(&ifexpr.cond) == CollectionResult::Incomplete
        {
            // If syntax is not recognized, return Incomplete.
            return CollectionResult::Incomplete;
        }
        // Walk else-if chain.
        if let Some((_, else_branch)) = &ifexpr.else_branch {
            match &**else_branch {
                Expr::If(nested) => self.collect_if_chain_variants(nested),
                // plain `else { ... }` should default to any node type
                _ => CollectionResult::Incomplete,
            }
        } else {
            CollectionResult::Complete
        }
    }

    /// Extracts AstKind variants from an `if let` condition like `if let AstKind::Xxx(..) = node.kind()`
    /// or `if let AstKind::Xxx(..) = node.kind() && other_condition`.
    fn extract_variants_from_if_let_condition(&mut self, cond: &Expr) -> CollectionResult {
        match cond {
            // Simple `if let` pattern
            Expr::Let(let_expr) => {
                // RHS must be `node.kind()`
                if is_node_kind_call(&let_expr.expr) {
                    self.extract_variants_from_pat(&let_expr.pat)
                } else {
                    CollectionResult::Incomplete
                }
            }
            // `if let ... && ...` pattern (from MSRV 1.88.0)
            // The entire condition might be a chain of binary && operations
            Expr::Binary(binary) if matches!(binary.op, syn::BinOp::And(_)) => {
                // Try to find the let expression in the leftmost part of the chain
                self.extract_from_binary_and_chain(binary)
            }
            _ => CollectionResult::Incomplete,
        }
    }

    /// Recursively extract from a binary && chain to find the let expression
    fn extract_from_binary_and_chain(&mut self, binary: &syn::ExprBinary) -> CollectionResult {
        // Check if the left side is another binary expression (nested &&)
        match &*binary.left {
            Expr::Binary(left_binary) if matches!(left_binary.op, syn::BinOp::And(_)) => {
                // Recursively check the left side
                self.extract_from_binary_and_chain(left_binary)
            }
            Expr::Let(let_expr) => {
                // Found the let expression
                if is_node_kind_call(&let_expr.expr) {
                    self.extract_variants_from_pat(&let_expr.pat)
                } else {
                    CollectionResult::Incomplete
                }
            }
            _ => CollectionResult::Incomplete,
        }
    }

    fn extract_variants_from_pat(&mut self, pat: &Pat) -> CollectionResult {
        match pat {
            Pat::Or(orpat) => {
                for p in &orpat.cases {
                    if self.extract_variants_from_pat(p) == CollectionResult::Incomplete {
                        return CollectionResult::Incomplete;
                    }
                }
                CollectionResult::Complete
            }
            Pat::TupleStruct(ts) => {
                if let Some(variant) = astkind_variant_from_path(&ts.path) {
                    self.node_types.insert(variant);
                    CollectionResult::Complete
                } else {
                    CollectionResult::Incomplete
                }
            }
            _ => CollectionResult::Incomplete,
        }
    }
}

use syn::{Expr, Pat, Stmt};

use crate::{
    CollectionResult, RuleRunnerData,
    node_type_set::NodeTypeSet,
    utils::{astkind_variant_from_path, executable_stmts, is_node_kind_call},
};

/// Detects top-level `let AstKind::... = node.kind() else { return; }` patterns in the `run` method.
pub struct LetElseDetector<'a> {
    node_types: NodeTypeSet,
    rule_runner_data: &'a RuleRunnerData,
}

impl<'a> LetElseDetector<'a> {
    pub fn from_run_func(
        run_func: &syn::ImplItemFn,
        rule_runner_data: &'a RuleRunnerData,
    ) -> Option<NodeTypeSet> {
        // Only consider when the body's first statement is `let AstKind::... = node.kind() else { ... }`,
        // and the body of the `else` is just `return`.
        let stmts = executable_stmts(&run_func.block);
        let first_stmt = *stmts.first()?;
        // Must be a local `let` statement
        let Stmt::Local(local) = first_stmt else { return None };
        // Must have an initializer that is a `node.kind()` call
        let Some(init) = &local.init else { return None };
        if !(is_node_kind_call(&init.expr) || is_node_kind_as_call(&init.expr)) {
            return None;
        }
        // Must have a diverging `else` block
        let Some(diverge) = &init.diverge else { return None };
        let diverge_expr = &*diverge.1;
        let Expr::Block(else_block) = diverge_expr else { return None };
        // The else block must have exactly one statement and it must be a `return`
        if else_block.block.stmts.len() != 1 {
            return None;
        }
        let Stmt::Expr(expr, _) = &else_block.block.stmts[0] else { return None };
        if !matches!(expr, Expr::Return(_)) {
            return None;
        }

        let mut detector = Self { node_types: NodeTypeSet::new(), rule_runner_data };

        if is_node_kind_as_call(&init.expr) {
            // If the initializer is `node.kind().as_<variant>()`, extract that variant.
            if let Expr::MethodCall(mc) = &*init.expr
                && let Some(variants) = detector.extract_variants_from_as_call(mc)
            {
                detector.node_types.extend(variants);
            }
        } else {
            // Otherwise, the initializer is `node.kind()`, so extract from the pattern.
            // Expecting `AstKind::Variant` pattern
            let result = detector.extract_variants_from_pat(&local.pat);
            if result == CollectionResult::Incomplete {
                return None;
            }
        }
        if detector.node_types.is_empty() {
            return None;
        }

        Some(detector.node_types)
    }

    fn extract_variants_from_pat(&mut self, pat: &Pat) -> CollectionResult {
        match pat {
            Pat::TupleStruct(ts) => {
                if let Some(variant) = astkind_variant_from_path(&ts.path) {
                    self.node_types.insert(variant);
                    CollectionResult::Complete
                } else {
                    CollectionResult::Incomplete
                }
            }
            _ => CollectionResult::Incomplete,
        }
    }

    fn extract_variants_from_as_call(&self, mc: &syn::ExprMethodCall) -> Option<NodeTypeSet> {
        // Looking for `node.kind().as_<snake_case_variant>()`
        let method_ident = mc.method.to_string();
        if !method_ident.starts_with("as_") || !mc.args.is_empty() {
            return None;
        }
        // Receiver must be `node.kind()`
        if !is_node_kind_call(&mc.receiver) {
            return None;
        }
        let snake_variant = &method_ident[3..]; // strip `as_`
        if snake_variant == "member_expression_kind" {
            return Some(self.rule_runner_data.member_expression_kinds.clone());
        }
        let mut node_type_set = NodeTypeSet::new();
        node_type_set.insert(snake_to_pascal_case(snake_variant));
        Some(node_type_set)
    }
}

/// Checks if is `node.kind().as_some_ast_kind()`
pub fn is_node_kind_as_call(expr: &Expr) -> bool {
    if let Expr::MethodCall(mc) = expr
        && mc.method.to_string().starts_with("as_")
        && mc.args.is_empty()
        && is_node_kind_call(&mc.receiver)
    {
        return true;
    }
    false
}

fn snake_to_pascal_case(s: &str) -> String {
    s.split('_')
        .filter(|seg| !seg.is_empty())
        .map(|seg| {
            let mut chars = seg.chars();
            match chars.next() {
                Some(first) => first.to_ascii_uppercase().to_string() + chars.as_str(),
                None => String::new(),
            }
        })
        .collect()
}

