/// Detects top-level `match node.kind() { ... }` patterns in the `run` method.
pub struct MatchDetector<'a> {
    node_types: NodeTypeSet,
    rule_runner_data: &'a RuleRunnerData,
}

impl<'a> MatchDetector<'a> {
    pub fn from_run_func(
        run_func: &syn::ImplItemFn,
        rule_runner_data: &'a RuleRunnerData,
    ) -> Option<NodeTypeSet> {
        // Only consider when the body's only statement is `match node.kind() { ... }`
        let stmts = executable_stmts(&run_func.block);
        if stmts.len() != 1 {
            return None;
        }
        let first_stmt = stmts[0];
        // Must be an expression statement
        let Stmt::Expr(expr, _) = first_stmt else { return None };
        // Must be a match expression
        let Expr::Match(match_expr) = expr else { return None };
        // The match expression's must be matching on a `node.kind()` call
        if !is_node_kind_call(&match_expr.expr) {
            return None;
        }

        let mut detector = Self { node_types: NodeTypeSet::new(), rule_runner_data };
        let result = detector.extract_variants_from_match_expr(match_expr);
        if detector.node_types.is_empty() || result == CollectionResult::Incomplete {
            return None;
        }

        Some(detector.node_types)
    }

    fn extract_variants_from_match_expr(
        &mut self,
        match_expr: &syn::ExprMatch,
    ) -> CollectionResult {
        let mut overall_result = CollectionResult::Complete;
        for arm in &match_expr.arms {
            let result = self.extract_variants_from_match_arm(arm);
            if result == CollectionResult::Incomplete {
                overall_result = CollectionResult::Incomplete;
            }
        }
        overall_result
    }

    fn extract_variants_from_match_arm(&mut self, arm: &Arm) -> CollectionResult {
        let pat = &arm.pat;
        match pat {
            Pat::TupleStruct(ts) => {
                if let Some(variant) = astkind_variant_from_path(&ts.path) {
                    // NOTE: If there is a guard, we assume that it may or may not be taken and collect all AST kinds
                    // regardless of the guard condition.
                    self.node_types.insert(variant);
                    CollectionResult::Complete
                } else {
                    CollectionResult::Incomplete
                }
            }
            Pat::Wild(_) => {
                // Body must be completely empty, or return empty type only `()`
                if let Expr::Block(block) = &*arm.body {
                    if block.block.stmts.is_empty() {
                        CollectionResult::Complete
                    } else {
                        CollectionResult::Incomplete
                    }
                } else if let Expr::Tuple(tuple) = &*arm.body {
                    if tuple.elems.is_empty() {
                        CollectionResult::Complete
                    } else {
                        CollectionResult::Incomplete
                    }
                } else {
                    CollectionResult::Incomplete
                }
            }
            Pat::Guard(guard) => {
                if let Pat::TupleStruct(ts) = guard.pat.as_ref() {
                    if let Some(variant) = astkind_variant_from_path(&ts.path) {
                        self.node_types.insert(variant);
                        return CollectionResult::Complete;
                    }
                    return CollectionResult::Incomplete;
                }
                let Pat::Ident(ident) = guard.pat.as_ref() else {
                    return CollectionResult::Incomplete;
                };
                if ident.subpat.is_some() {
                    return CollectionResult::Incomplete;
                }
                // Look for a `member_expr if member_expr.is_member_expression_kind() => {` arm
                if let Expr::MethodCall(method_call) = &*guard.guard
                    && method_call.method == "is_member_expression_kind"
                    && method_call.args.is_empty()
                {
                    // We have a match, so we can add MemberExpression to the set of node types
                    self.node_types.extend(self.rule_runner_data.member_expression_kinds.clone());
                    CollectionResult::Complete
                } else {
                    CollectionResult::Incomplete
                }
            }
            _ => CollectionResult::Incomplete,
        }
    }
}

use syn::{Expr, Pat, Stmt};

use crate::{node_type_set::NodeTypeSet, utils::find_impl_function};

/// Fetches the current list of variants that can be returned by `AstKind::as_member_expression_kind()`.
/// We read the source file to avoid hardcoding the list here and ensure this will stay updated.
pub fn get_member_expression_kinds() -> Option<NodeTypeSet> {
    // Read crates/oxc_ast/src/ast_kind_impl.rs and extract all variants in `as_member_expression_kind` function
    let ast_kind_impl_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()?
        .parent()?
        .join("crates")
        .join("oxc_ast")
        .join("src")
        .join("ast_kind_impl.rs");
    let content = std::fs::read_to_string(ast_kind_impl_path).ok()?;
    let syntax = syn::parse_file(&content).ok()?;
    let mut node_type_set = NodeTypeSet::new();
    for item in syntax.items {
        if let syn::Item::Impl(impl_block) = item
            && let syn::Type::Path(type_path) = impl_block.self_ty.as_ref()
            && type_path.path.segments.last()?.ident == "AstKind"
        {
            let impl_fn = find_impl_function(&impl_block, "as_member_expression_kind")
                .expect("as_member_expression_kind function not found");

            // Look for `match self { ... }` inside the function body
            if impl_fn.block.stmts.len() != 1 {
                return None;
            }
            let stmt = &impl_fn.block.stmts[0];
            if let Stmt::Expr(Expr::Match(match_expr), _) = stmt {
                for arm in &match_expr.arms {
                    if let Pat::TupleStruct(ts) = &arm.pat
                        && let Some(variant) = self_astkind_variant_from_path(&ts.path)
                    {
                        node_type_set.insert(variant);
                    }
                }
                if !node_type_set.is_empty() {
                    return Some(node_type_set);
                }
            }
        }
    }
    None
}

fn self_astkind_variant_from_path(path: &syn::Path) -> Option<String> {
    // Expect `Self::Variant`
    if path.segments.len() != 2 {
        return None;
    }
    if path.segments[0].ident != "Self" {
        return None;
    }
    Some(path.segments[1].ident.to_string())
}

use rustc_hash::FxHashSet;

/// A set of AstKind variants, used for storing the unique node types detected in a rule,
/// or a portion of the rule file.
#[derive(Clone)]
pub struct NodeTypeSet {
    node_types: FxHashSet<String>,
}

impl NodeTypeSet {
    /// Create a new set of node variants
    pub fn new() -> Self {
        Self { node_types: FxHashSet::default() }
    }

    /// Insert a variant into the set
    pub fn insert(&mut self, node_type_variant: String) {
        self.node_types.insert(node_type_variant);
    }

    /// Returns `true` if there are no node types in the set.
    pub fn is_empty(&self) -> bool {
        self.node_types.is_empty()
    }

    /// Extend the set with another set of node types.
    pub fn extend(&mut self, other: NodeTypeSet) {
        self.node_types.extend(other.node_types);
    }

    /// Returns the generated code string to initialize an `AstTypesBitset` with the variants
    /// in this set.
    pub fn to_ast_type_bitset_string(&self) -> String {
        let mut variants: Vec<&str> =
            self.node_types.iter().map(std::string::String::as_str).collect();
        variants.sort_unstable();
        let type_idents: Vec<String> =
            variants.into_iter().map(|v| format!("AstType::{v}")).collect();
        format!("AstTypesBitset::from_types(&[{}])", type_idents.join(", "))
    }
}
